command:
$ErrorActionPreference = 'Stop'
$requiredAncestor = '357a239964fc6fab529cbac38187eaf822c00a7b'
git merge-base --is-ancestor $requiredAncestor HEAD
if ($LASTEXITCODE -ne 0) { throw 'Expected DCOIR Review v19 source commit is not an ancestor of the executor checkout' }
python -m py_compile .github/dcoir_review/scripts/dcoir_review_required_runtime_patch_v19.py .github/dcoir_review/scripts/dcoir_review_required_runtime_patch_v19_selftest.py .github/dcoir_review/scripts/dcoir_review/entrypoint.py
if ($LASTEXITCODE -ne 0) { throw 'v19 py_compile failed' }
python .github/dcoir_review/scripts/dcoir_review_required_runtime_patch_v19_selftest.py
if ($LASTEXITCODE -ne 0) { throw 'v19 selftest failed' }
python .github/dcoir_review/scripts/openrouter_pr_review_pareto_context_selftest.py
if ($LASTEXITCODE -ne 0) { throw 'Pareto context selftest failed' }
python .github/dcoir_review/scripts/openrouter_pr_review_hardened_selftest.py
if ($LASTEXITCODE -ne 0) { throw 'Hardened selftest failed' }
python .github/dcoir_review/scripts/openrouter_pr_review_quality_recovery_selftest.py
if ($LASTEXITCODE -ne 0) { throw 'Quality recovery selftest failed' }
python .github/dcoir_review/scripts/validate-codeql-security-workflow.py
if ($LASTEXITCODE -ne 0) { throw 'CodeQL workflow validator failed' }
git diff --check $requiredAncestor HEAD -- .github/dcoir_review
if ($LASTEXITCODE -ne 0) { throw 'DCOIR Review diff check failed' }
Write-Host ('validated_source_ancestor=' + $requiredAncestor)
Write-Host ('executor_head=' + (& git rev-parse HEAD).Trim())
Write-Host 'dcoir_review_v19_validation=PASS'
